-- Arbeitsrecht Berufsbildung > Wirtschaftliche Zusammenhänge > Unternehmensformen > GbR
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Haften die Gesellschafter einer IT-GbR persönlich und unbeschränkt für die Schulden der Gesellschaft?', 2, '[{"text": "Ja", "correct": true, "because": "GbR-Gesellschafter haften persönlich und unbeschränkt"}, {"text": "Nein", "correct": false, "because": "Persönliche Haftung ist ein Merkmal der GbR"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine IT-GbR ein Mindestkapital bei der Gründung einbringen?', 2, '[{"text": "Nein", "correct": true, "because": "Die GbR hat keine Mindestkapitalvorgabe"}, {"text": "Ja", "correct": false, "because": "Kein Mindestkapital erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine IT-GbR von einer einzelnen Person gegründet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Die GbR erfordert mindestens zwei Gesellschafter"}, {"text": "Ja", "correct": false, "because": "Mehrere Gesellschafter sind nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine IT-GbR verpflichtet, einen Jahresabschluss beim Handelsregister einzureichen?', 2, '[{"text": "Nein", "correct": true, "because": "GbR hat keine Offenlegungspflicht im Handelsregister"}, {"text": "Ja", "correct": false, "because": "Keine Veröffentlichung vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine IT-GbR die Einnahmen-Überschuss-Rechnung (EÜR) zur Gewinnermittlung nutzen?', 2, '[{"text": "Ja", "correct": true, "because": "EÜR ist für GbR zulässig, wenn kein Handelsgewerbe"}, {"text": "Nein", "correct": false, "because": "EÜR ist üblich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptmerkmal einer IT-GbR?', 2, '[{"text": "Unbeschränkte persönliche Haftung", "correct": true, "because": "Gesellschafter haften voll"}, {"text": "Beschränkte Haftung", "correct": false, "because": "Das gilt für GmbH"}, {"text": "Mindestkapital erforderlich", "correct": false, "because": "Kein Mindestkapital nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Gesellschafter benötigt eine IT-GbR mindestens?', 3, '[{"text": "Zwei", "correct": true, "because": "GbR ist eine Personengesellschaft mit mindestens zwei Personen"}, {"text": "Einer", "correct": false, "because": "Einzelperson nicht möglich"}, {"text": "Drei", "correct": false, "because": "Zwei reichen aus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer führt die Geschäfte einer IT-GbR?', 3, '[{"text": "Alle Gesellschafter gemeinsam", "correct": true, "because": "Gesellschafter führen die Geschäfte zusammen"}, {"text": "Ein Geschäftsführer", "correct": false, "because": "Das gilt für GmbH"}, {"text": "Ein Aufsichtsrat", "correct": false, "because": "Das gilt für AG"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt die Gründung einer IT-GbR?', 2, '[{"text": "Bürgerliches Gesetzbuch (BGB)", "correct": true, "because": "BGB regelt die GbR (§§ 705 ff.)"}, {"text": "Handelsgesetzbuch (HGB)", "correct": false, "because": "HGB gilt für Handelsgesellschaften"}, {"text": "GmbHG", "correct": false, "because": "Gilt für GmbH"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Vorteil der GbR als Unternehmensform für einen IT-Betrieb?', 3, '[{"text": "Einfache Gründung", "correct": true, "because": "Keine notarielle Beurkundung nötig"}, {"text": "Beschränkte Haftung", "correct": false, "because": "GbR haftet unbeschränkt"}, {"text": "Hohe Kapitalanforderung", "correct": false, "because": "Kein Mindestkapital nötig"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat eine IT-GbR?', 4, '[{"text": "Unbeschränkte persönliche Haftung", "correct": true, "because": "Gesellschafter haften voll"}, {"text": "Mindestens zwei Gesellschafter", "correct": true, "because": "GbR ist Personengesellschaft"}, {"text": "Mindestkapital von 25.000 Euro", "correct": false, "because": "Kein Mindestkapital nötig"}, {"text": "Einfache Gründung ohne Notar", "correct": true, "because": "Keine notarielle Beurkundung erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die GbR als Unternehmensform für einen IT-Betrieb?', 3, '[{"text": "Einfache und kostengünstige Gründung", "correct": true, "because": "Keine Formalien oder Mindestkapital"}, {"text": "Flexibilität bei Entscheidungen", "correct": true, "because": "Gesellschafter entscheiden gemeinsam"}, {"text": "Beschränkte Haftung", "correct": false, "because": "GbR haftet unbeschränkt"}, {"text": "Geringer Verwaltungsaufwand", "correct": true, "because": "Wenige gesetzliche Vorgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat die GbR als Unternehmensform für einen IT-Betrieb?', 4, '[{"text": "Unbeschränkte Haftung", "correct": true, "because": "Gesellschafter haften persönlich"}, {"text": "Abhängigkeit von Gesellschaftern", "correct": true, "because": "Fehlentscheidungen treffen alle"}, {"text": "Hohe Gründungskosten", "correct": false, "because": "Gründung ist kostengünstig"}, {"text": "Eingeschränkte Kapitalbeschaffung", "correct": true, "because": "Nur eigenes Kapital der Gesellschafter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche rechtlichen Anforderungen gelten für eine IT-GbR?', 3, '[{"text": "Gewerbeanmeldung", "correct": true, "because": "Pflicht bei Gewerbebetrieb"}, {"text": "Steuerliche Registrierung", "correct": true, "because": "Steuerpflicht besteht"}, {"text": "Eintragung ins Handelsregister", "correct": false, "because": "Nur bei Handelsgewerbe"}, {"text": "EÜR oder Buchführung bei Handelsgewerbe", "correct": true, "because": "Abhängig von Gewerbeart"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet die GbR von einer OHG für einen IT-Betrieb?', 3, '[{"text": "GbR ist keine Handelsgesellschaft", "correct": true, "because": "OHG ist im HGB geregelt"}, {"text": "OHG hat strengere Buchführungspflicht", "correct": true, "because": "GbR kann EÜR nutzen"}, {"text": "GbR hat Mindestkapital", "correct": false, "because": "Kein Mindestkapital bei GbR"}, {"text": "GbR hat weniger Formalien", "correct": true, "because": "OHG muss ins Handelsregister"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Eine IT-GbR haftet mit dem Privatvermögen der Gesellschafter. b) Eine IT-GbR benötigt ein Mindestkapital.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Haftung ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine IT-GbR kann einfach gegründet werden. b) Eine IT-GbR benötigt mindestens zwei Gesellschafter.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Einfache Gründung und zwei Gesellschafter"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine IT-GbR hat keine Veröffentlichungspflicht. b) Eine GbR kann von einer Person gegründet werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Veröffentlichung, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Eine IT-GbR bietet Flexibilität bei Entscheidungen. b) Eine GbR haftet nur mit dem Gesellschaftsvermögen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Flexibilität ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine IT-GbR wird durch das BGB geregelt. b) Eine GbR muss ins Handelsregister eingetragen werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "BGB ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

